# Reviewed under AGENTS.md
from __future__ import annotations

from collections import OrderedDict
from typing import Generic, TypeVar

K = TypeVar('K')
V = TypeVar('V')


class LRUCache(Generic[K, V]):
    """A fixed-capacity cache that evicts the least recently used key.

    Both :meth:`get` and :meth:`put` count as a use: the key becomes the most
    recently used one.
    """

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError('capacity must be at least 1')
        self._capacity = capacity
        # Most recently used key last.
        self._data: OrderedDict[K, V] = OrderedDict()

    @property
    def capacity(self) -> int:
        return self._capacity

    def get(self, key: K) -> V | None:
        """Return the value for ``key``, marking it as recently used."""
        try:
            value = self._data[key]
        except KeyError:
            return None
        self._data.move_to_end(key)
        return value

    def put(self, key: K, value: V) -> None:
        """Insert or update ``key``, evicting the least recently used key if needed."""
        if key in self._data:
            self._data.move_to_end(key)
        elif len(self._data) >= self._capacity:
            self._data.popitem(last=False)
        self._data[key] = value

    def __len__(self) -> int:
        return len(self._data)
